function debounce(fn, wait, immediate = false) {
  let timer = null;
  return function (...args) {
    if (timer) clearTimeout(timer);
    if (immediate && !timer) {
      fn.apply(this, args); // 首次立即执行
    }
    timer = setTimeout(() => {
      if (!immediate) fn.apply(this, args);
      timer = null;
    }, wait);
  };
}

区别：防抖是事件停止触发 wait 毫秒后才执行一次（如搜索框输入联想、窗口 resize 结束后计算）；节流是保证 wait 毫秒内最多执行一次（如滚动加载、按钮防连点）。

function useThrottle(fn, wait) {
  const last = useRef(0); const timer = useRef(null); const fnRef = useRef(fn); fnRef.current = fn;
  return useCallback((...args) => {
    const now = Date.now(); const remain = wait - (now - last.current);
    if (remain <= 0) { last.current = now; fnRef.current(...args); }
    else if (!timer.current) { timer.current = setTimeout(() => { last.current = Date.now(); timer.current = null; fnRef.current(...args); }, remain); }
  }, [wait]);
}
节流保证「wait 毫秒内最多执行一次」，适合高频连续事件（滚动、鼠标移动）；防抖是「事件停止 wait 毫秒后才执行一次」，适合输入联想。
